async function reviewJob(job) {
  const res = await openInvoiceModal({ mode: "review", job });
  if (res) {
    job.state = "saved";
    job.savedLabel = `Guardada como ${res.invoice.number || "sin número"} · ${fmtEUR(res.invoice.total)}`;
  } else {
    job.state = "skipped";
  }
  paintIngest();
}

